const body = $input.first().json.body || $input.first().json;
const sessionId = body.sessionId || body.from || body.phone || null;
const message = body.message || body.text || body.body || '';
const jobOpeningId = body.jobOpeningId || body.job_opening_id || null;
const step = body.step || 'start';
const answers = body.answers || {};
const candidateData = body.candidateData || {};
return [{ json: { sessionId, message, jobOpeningId, step, answers, candidateData } }];

const parsed = $('Parsear Mensagem').first().json;
const job = ($('Buscar Vaga').first().json || [])[0];
const questions = $('Buscar Perguntas').first().json || [];

if (!job) {
  return [{ json: { action: 'reply', message: '❌ Vaga não encontrada ou encerrada.', done: true } }];
}

const step = parsed.step;
const answers = parsed.answers || {};
const candidateData = parsed.candidateData || {};

// Fluxo de coleta de dados pessoais
if (step === 'start') {
  return [{ json: { action: 'reply', message: `Olá! 👋 Você está se candidatando para a vaga *${job.title}*.\n\nPrimeiro, me diga seu *nome completo*:`, nextStep: 'collect_name', jobOpeningId: job.id, organizationId: job.organization_id, answers, candidateData } }];
}
if (step === 'collect_name') {
  return [{ json: { action: 'reply', message: 'Ótimo! Agora me informe seu *e-mail*:', nextStep: 'collect_email', jobOpeningId: job.id, organizationId: job.organization_id, answers, candidateData: { ...candidateData, full_name: parsed.message } } }];
}
if (step === 'collect_email') {
  const email = parsed.message.trim().toLowerCase();
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    return [{ json: { action: 'reply', message: '⚠️ E-mail inválido. Por favor, informe um e-mail válido:', nextStep: 'collect_email', jobOpeningId: job.id, organizationId: job.organization_id, answers, candidateData } }];
  }
  return [{ json: { action: 'reply', message: 'E agora seu *telefone* (com DDD):', nextStep: 'collect_phone', jobOpeningId: job.id, organizationId: job.organization_id, answers, candidateData: { ...candidateData, email } } }];
}
if (step === 'collect_phone') {
  const updatedCandidate = { ...candidateData, phone: parsed.message.trim() };
  if (questions.length === 0) {
    return [{ json: { action: 'submit', jobOpeningId: job.id, organizationId: job.organization_id, answers, candidateData: updatedCandidate } }];
  }
  const firstQ = questions[0];
  return [{ json: { action: 'reply', message: `Perfeito! Agora algumas perguntas sobre a vaga.\n\n*Pergunta 1/${questions.length}:*\n${firstQ.question_text}`, nextStep: `question_0`, questionIndex: 0, jobOpeningId: job.id, organizationId: job.organization_id, answers, candidateData: updatedCandidate } }];
}

// Fluxo de perguntas
if (step.startsWith('question_')) {
  const idx = parseInt(step.replace('question_', ''), 10);
  const currentQ = questions[idx];
  const updatedAnswers = { ...answers, [currentQ.id]: parsed.message };
  const nextIdx = idx + 1;
  if (nextIdx < questions.length) {
    const nextQ = questions[nextIdx];
    return [{ json: { action: 'reply', message: `*Pergunta ${nextIdx + 1}/${questions.length}:*\n${nextQ.question_text}`, nextStep: `question_${nextIdx}`, questionIndex: nextIdx, jobOpeningId: job.id, organizationId: job.organization_id, answers: updatedAnswers, candidateData } }];
  }
  return [{ json: { action: 'submit', jobOpeningId: job.id, organizationId: job.organization_id, answers: updatedAnswers, candidateData } }];
}

return [{ json: { action: 'reply', message: 'Não entendi. Tente novamente.', done: false } }];

const d = $input.first().json;
const supabaseUrl = $env.SUPABASE_URL;
const supabaseKey = $env.SUPABASE_SERVICE_KEY;

// 1. Verificar duplicata
const checkRes = await $http.request({
  method: 'GET',
  url: `${supabaseUrl}/rest/v1/candidates?organization_id=eq.${d.organizationId}&email=eq.${encodeURIComponent(d.candidateData.email)}&select=id`,
  headers: { apikey: supabaseKey, Authorization: `Bearer ${supabaseKey}` }
});
const existing = checkRes[0];
let candidateId;

if (existing?.id) {
  // Verificar se já candidatou a esta vaga
  const appCheck = await $http.request({
    method: 'GET',
    url: `${supabaseUrl}/rest/v1/applications?job_opening_id=eq.${d.jobOpeningId}&candidate_id=eq.${existing.id}&select=id`,
    headers: { apikey: supabaseKey, Authorization: `Bearer ${supabaseKey}` }
  });
  if (appCheck[0]) {
    return [{ json: { message: '⚠️ Você já se candidatou a esta vaga anteriormente.', done: true } }];
  }
  candidateId = existing.id;
} else {
  // Criar candidato
  const newCandidate = await $http.request({
    method: 'POST',
    url: `${supabaseUrl}/rest/v1/candidates`,
    headers: { apikey: supabaseKey, Authorization: `Bearer ${supabaseKey}`, 'Content-Type': 'application/json', Prefer: 'return=representation' },
    body: { organization_id: d.organizationId, full_name: d.candidateData.full_name, email: d.candidateData.email, phone: d.candidateData.phone || null }
  });
  candidateId = newCandidate[0]?.id;
}

if (!candidateId) throw new Error('Falha ao criar candidato');

// 2. Criar candidatura
const answersArray = Object.entries(d.answers || {}).map(([qId, ans]) => ({ question_id: qId, answer: ans, score: 0, max_score: 0, question_text: '', question_type: 'text' }));
await $http.request({
  method: 'POST',
  url: `${supabaseUrl}/rest/v1/applications`,
  headers: { apikey: supabaseKey, Authorization: `Bearer ${supabaseKey}`, 'Content-Type': 'application/json', Prefer: 'return=minimal' },
  body: { organization_id: d.organizationId, job_opening_id: d.jobOpeningId, candidate_id: candidateId, answers: answersArray, source: 'agent', score_auto: 0, score_total: 0, score_max: 0, score_percent: 0 }
});

return [{ json: { message: `✅ Candidatura enviada com sucesso!\n\nObrigado, *${d.candidateData.full_name}*! Nossa equipe analisará seu perfil e entrará em contato em breve.`, done: true } }];
